import{_ as a,o as e,c as o,ag as l}from"./chunks/framework.D7Pdja0E.js";const q=JSON.parse('{"title":"팝빌 연동 — 세금계산서 발행 + 입금내역 자동 수집","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/finance-popbill.md","filePath":"04-org-admin-guide/finance-popbill.md","lastUpdated":1780579853000}'),i={name:"04-org-admin-guide/finance-popbill.md"};function r(n,t,d,h,s,c){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="팝빌-연동-—-세금계산서-발행-입금내역-자동-수집" tabindex="-1">팝빌 연동 — 세금계산서 발행 + 입금내역 자동 수집 <a class="header-anchor" href="#팝빌-연동-—-세금계산서-발행-입금내역-자동-수집" aria-label="Permalink to &quot;팝빌 연동 — 세금계산서 발행 + 입금내역 자동 수집&quot;">​</a></h1><p>워크허브 재무관리는 <strong>팝빌(Popbill)</strong> 의 두 가지 API 를 사용해 매출 자동화를 구현합니다:</p><table tabindex="0"><thead><tr><th>모듈</th><th>역할</th><th>사용 시점</th></tr></thead><tbody><tr><td><strong>팝빌 전자세금계산서</strong></td><td>매출 확정 시 세금계산서 자동 발행 + 발행 결과 자동 갱신</td><td>입금 확정 → 자동 발행 / 화면에서 수동 발행</td></tr><tr><td><strong>팝빌 계좌조회 (EasyFin)</strong></td><td>등록한 사업자 계좌의 입금내역을 매일 자동 수집 → 매출 자동 매칭</td><td>백그라운드 (시스템 cron)</td></tr></tbody></table><blockquote><p><strong>기관관리자 자가 등록</strong>: 본 화면에서 입력만 하면 즉시 활성 — 시스템관리자(워크허브 운영자) 개입 없이 본인이 등록·해제·테스트할 수 있습니다.</p></blockquote><hr><h2 id="_1-사전-준비-—-팝빌-가입-파트너-키-발급" tabindex="-1">1. 사전 준비 — 팝빌 가입 + 파트너 키 발급 <a class="header-anchor" href="#_1-사전-준비-—-팝빌-가입-파트너-키-발급" aria-label="Permalink to &quot;1. 사전 준비 — 팝빌 가입 + 파트너 키 발급&quot;">​</a></h2><h3 id="_1-팝빌-회원-가입" tabindex="-1">1) 팝빌 회원 가입 <a class="header-anchor" href="#_1-팝빌-회원-가입" aria-label="Permalink to &quot;1) 팝빌 회원 가입&quot;">​</a></h3><p><a href="https://www.popbill.com" target="_blank" rel="noreferrer">https://www.popbill.com</a> → 회원가입 → <strong>&quot;사업자 회원&quot;</strong> 으로 가입 (개인 회원 불가)</p><p>가입 시 필요:</p><ul><li>사업자등록증</li><li>공동인증서 (전자세금계산서 발급용)</li></ul><h3 id="_2-파트너-연동회원-신청" tabindex="-1">2) 파트너(연동회원) 신청 <a class="header-anchor" href="#_2-파트너-연동회원-신청" aria-label="Permalink to &quot;2) 파트너(연동회원) 신청&quot;">​</a></h3><p>팝빌은 일반 회원과 별도로 <strong>&quot;파트너 회원&quot;</strong> (= 연동회원) 등록이 필요합니다. 워크허브 같은 외부 시스템이 API 로 호출하려면 파트너 자격이어야 LinkID/SecretKey 를 받을 수 있습니다.</p><ol><li>팝빌 로그인 → 상단 <strong>&quot;연동회원 신청&quot;</strong> 메뉴</li><li>신청서 작성 + 사업자 자료 첨부</li><li>보통 1~2 영업일 내 승인 메일</li></ol><h3 id="_3-linkid-secretkey-발급" tabindex="-1">3) LinkID / SecretKey 발급 <a class="header-anchor" href="#_3-linkid-secretkey-발급" aria-label="Permalink to &quot;3) LinkID / SecretKey 발급&quot;">​</a></h3><p>승인 후:</p><ol><li>팝빌 로그인 → <strong>마이페이지 → 연동정보 관리</strong></li><li>화면에 표시되는 다음 값을 메모: <ul><li><strong>LinkID</strong> — 워크허브에 입력할 파트너 ID (예: <code>MyCompany</code>)</li><li><strong>SecretKey</strong> — 비밀키 (예: <code>aB3xY9zQwer...</code>) — <strong>외부 노출 금지</strong></li><li><strong>사업자등록번호</strong> — 팝빌 가입 시 등록한 본인 사업자번호</li></ul></li></ol><h3 id="_4-세금계산서만-공동인증서-등록" tabindex="-1">4) (세금계산서만) 공동인증서 등록 <a class="header-anchor" href="#_4-세금계산서만-공동인증서-등록" aria-label="Permalink to &quot;4) (세금계산서만) 공동인증서 등록&quot;">​</a></h3><p>전자세금계산서 발급은 법적으로 공동인증서 필수:</p><ol><li>팝빌 로그인 → <strong>마이페이지 → 인증서 관리</strong></li><li>본인 사업자 명의 공동인증서 업로드 + 비밀번호 등록</li><li>유효기간 만료 전 갱신 필수 (메일 알림 옴)</li></ol><blockquote><p>워크허브는 인증서를 직접 다루지 않습니다 — 팝빌 측에 등록된 인증서를 팝빌이 자동 사용.</p></blockquote><hr><h2 id="_2-워크허브에-팝빌-연결하기" tabindex="-1">2. 워크허브에 팝빌 연결하기 <a class="header-anchor" href="#_2-워크허브에-팝빌-연결하기" aria-label="Permalink to &quot;2. 워크허브에 팝빌 연결하기&quot;">​</a></h2><h3 id="_1-화면-이동" tabindex="-1">1) 화면 이동 <a class="header-anchor" href="#_1-화면-이동" aria-label="Permalink to &quot;1) 화면 이동&quot;">​</a></h3><p>좌측 사이드바 <strong>재무관리 → 외부 연동</strong> 클릭, 또는 <code>/app/finance/integrations</code> 직접 접속.</p><blockquote><p>메뉴가 안 보이면: 기관관리자에게 <strong>재무관리 모듈 활성화</strong> 요청.</p></blockquote><h3 id="_2-팝빌-—-전자세금계산서-카드의-연결하기-클릭" tabindex="-1">2) &quot;팝빌 — 전자세금계산서&quot; 카드의 [연결하기] 클릭 <a class="header-anchor" href="#_2-팝빌-—-전자세금계산서-카드의-연결하기-클릭" aria-label="Permalink to &quot;2) &quot;팝빌 — 전자세금계산서&quot; 카드의 [연결하기] 클릭&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 팝빌 — 전자세금계산서                          [연결하기]   │</span></span>
<span class="line"><span>│ 세금계산서 자동 발행. 공동인증서를 팝빌에 사전 등록 필요.      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-자격증명-입력-모달" tabindex="-1">3) 자격증명 입력 모달 <a class="header-anchor" href="#_3-자격증명-입력-모달" aria-label="Permalink to &quot;3) 자격증명 입력 모달&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>입력 값</th><th>비고</th></tr></thead><tbody><tr><td><strong>LinkID</strong></td><td>팝빌 마이페이지의 LinkID</td><td>필수</td></tr><tr><td><strong>SecretKey</strong></td><td>팝빌 마이페이지의 SecretKey</td><td>필수 (저장 시 AES-GCM 암호화)</td></tr><tr><td><strong>사업자등록번호</strong></td><td>본인 사업자번호 (<code>1234567890</code> 형식, 하이픈 가능)</td><td>필수</td></tr><tr><td>팝빌 회원 ID</td><td>일반 회원 ID (있으면)</td><td>선택</td></tr><tr><td>인증서 식별자</td><td>M2 단계 — 비워두면 됨</td><td>선택</td></tr></tbody></table><p>[저장] 클릭 → 백엔드에서 AES-GCM 암호화 후 <code>org_external_connections</code> 테이블에 저장.</p><h3 id="_4-연결-테스트-—-테스트-버튼" tabindex="-1">4) 연결 테스트 — [테스트] 버튼 <a class="header-anchor" href="#_4-연결-테스트-—-테스트-버튼" aria-label="Permalink to &quot;4) 연결 테스트 — [테스트] 버튼&quot;">​</a></h3><p>저장된 카드 우측의 <strong>[연결 테스트]</strong> 클릭 → 팝빌 API 호출:</p><ul><li>✅ <strong>성공</strong>: &quot;연결 정상 — 잔여포인트 12,345원&quot; 같은 메시지</li><li>❌ <strong>실패</strong>: 메시지에 원인 표시 (자격증명 불일치 / 사업자번호 오타 / 인증서 미등록 등)</li></ul><h3 id="_5-팝빌-—-계좌조회-easyfin-도-동일하게-등록" tabindex="-1">5) &quot;팝빌 — 계좌조회 (EasyFin)&quot; 도 동일하게 등록 <a class="header-anchor" href="#_5-팝빌-—-계좌조회-easyfin-도-동일하게-등록" aria-label="Permalink to &quot;5) &quot;팝빌 — 계좌조회 (EasyFin)&quot; 도 동일하게 등록&quot;">​</a></h3><p>같은 LinkID/SecretKey/사업자번호 사용 (팝빌 계정 1개 = 두 모듈 공유).</p><p>추가 입력:</p><ul><li><strong>환경</strong>: <code>prod</code> (운영) 또는 <code>test</code> (팝빌 테스트 모드). 기본 <code>prod</code>.</li></ul><hr><h2 id="_3-동작-확인" tabindex="-1">3. 동작 확인 <a class="header-anchor" href="#_3-동작-확인" aria-label="Permalink to &quot;3. 동작 확인&quot;">​</a></h2><h3 id="전자세금계산서" tabindex="-1">전자세금계산서 <a class="header-anchor" href="#전자세금계산서" aria-label="Permalink to &quot;전자세금계산서&quot;">​</a></h3><h4 id="자동-발행-—-입금-확정-시" tabindex="-1">자동 발행 — 입금 확정 시 <a class="header-anchor" href="#자동-발행-—-입금-확정-시" aria-label="Permalink to &quot;자동 발행 — 입금 확정 시&quot;">​</a></h4><ol><li>재무관리 → 매출 대장에서 청구 건 생성</li><li>팝빌 계좌조회로 입금이 자동 매칭되거나 사용자가 수동 매칭</li><li><strong>&quot;입금 확정&quot;</strong> 처리 시 → 백엔드가 자동으로 팝빌 정발행 호출</li><li>발행 결과는 1~3분 내 팝빌 → 워크허브 웹훅으로 자동 갱신</li><li>매출 행 옆 <strong>&quot;세금계산서: 발행완료&quot;</strong> 배지 표시 + PDF 링크</li></ol><h4 id="수동-발행-—-화면에서" tabindex="-1">수동 발행 — 화면에서 <a class="header-anchor" href="#수동-발행-—-화면에서" aria-label="Permalink to &quot;수동 발행 — 화면에서&quot;">​</a></h4><p>매출 대장의 청구 건 우측 <strong>[세금계산서 발행]</strong> 버튼 → 수신자 정보 확인 → [확인]</p><h4 id="발행-결과-자동-갱신" tabindex="-1">발행 결과 자동 갱신 <a class="header-anchor" href="#발행-결과-자동-갱신" aria-label="Permalink to &quot;발행 결과 자동 갱신&quot;">​</a></h4><p>팝빌이 발행 처리(승인/실패) 가 완료되면 워크허브에 콜백 → 화면 즉시 갱신.</p><blockquote><p>이게 동작하려면 워크허브 측 운영자가 시스템 환경에 <code>POPBILL_WEBHOOK_SECRET</code> + 팝빌 콘솔에 콜백 URL 을 등록해야 합니다 (운영자 1회 작업, 기관관리자 무관).</p></blockquote><h3 id="계좌조회-입금내역" tabindex="-1">계좌조회 (입금내역) <a class="header-anchor" href="#계좌조회-입금내역" aria-label="Permalink to &quot;계좌조회 (입금내역)&quot;">​</a></h3><h4 id="사업자-계좌-등록-팝빌-측" tabindex="-1">사업자 계좌 등록 (팝빌 측) <a class="header-anchor" href="#사업자-계좌-등록-팝빌-측" aria-label="Permalink to &quot;사업자 계좌 등록 (팝빌 측)&quot;">​</a></h4><ol><li>팝빌 로그인 → <strong>계좌조회 메뉴 → 계좌 추가</strong></li><li>본인 사업자 명의 은행/계좌 추가</li><li>ARS 또는 OTP 로 본인 인증</li></ol><h4 id="워크허브에서-폴링" tabindex="-1">워크허브에서 폴링 <a class="header-anchor" href="#워크허브에서-폴링" aria-label="Permalink to &quot;워크허브에서 폴링&quot;">​</a></h4><ul><li>매일 새벽 워크허브 cron 이 팝빌 EasyFin API 호출 → 신규 입금 내역 가져옴</li><li>입금자명 + 금액으로 매출 청구 건에 자동 매칭</li><li>매칭 후보가 여러 건이면 → 입금 매칭 보류함에 쌓임 → 사용자가 수동 선택</li></ul><hr><h2 id="_4-faq" tabindex="-1">4. FAQ <a class="header-anchor" href="#_4-faq" aria-label="Permalink to &quot;4. FAQ&quot;">​</a></h2><h3 id="q-워크허브에-등록한-linkid-secretkey-가-외부로-유출되지-않나요" tabindex="-1">Q. 워크허브에 등록한 LinkID/SecretKey 가 외부로 유출되지 않나요? <a class="header-anchor" href="#q-워크허브에-등록한-linkid-secretkey-가-외부로-유출되지-않나요" aria-label="Permalink to &quot;Q. 워크허브에 등록한 LinkID/SecretKey 가 외부로 유출되지 않나요?&quot;">​</a></h3><ul><li>저장 시 <strong>AES-GCM 암호화</strong> — 마스터 키는 DB 밖에 보관 (워크허브 운영자도 평문 조회 불가)</li><li>화면 응답에는 SecretKey 평문이 절대 포함되지 않음 (서버에서 마스킹)</li><li>본인 외 다른 기관은 본인 자격증명에 접근 불가</li></ul><h3 id="q-사업자번호를-잘못-입력했어요-수정-가능" tabindex="-1">Q. 사업자번호를 잘못 입력했어요. 수정 가능? <a class="header-anchor" href="#q-사업자번호를-잘못-입력했어요-수정-가능" aria-label="Permalink to &quot;Q. 사업자번호를 잘못 입력했어요. 수정 가능?&quot;">​</a></h3><ul><li>외부 연동 화면 → 카드의 <strong>[수정]</strong> 버튼 → 새 값 입력 → [저장]</li><li>사업자번호 변경은 자동 발행에 영향 — 매출 대장에 등록된 공급자 사업자번호와 일치해야 합니다.</li></ul><h3 id="q-연결-테스트가-credentials-invalid-로-실패합니다" tabindex="-1">Q. 연결 테스트가 &quot;credentials invalid&quot; 로 실패합니다. <a class="header-anchor" href="#q-연결-테스트가-credentials-invalid-로-실패합니다" aria-label="Permalink to &quot;Q. 연결 테스트가 &quot;credentials invalid&quot; 로 실패합니다.&quot;">​</a></h3><p>체크 순서:</p><ol><li><strong>LinkID 가 본인 회원 ID 가 아닌 파트너 LinkID 인지</strong> (혼동 빈도 1위)</li><li>SecretKey 복사 시 공백/줄바꿈 포함 여부</li><li>사업자번호 오타</li><li>팝빌 콘솔에서 LinkID 가 &quot;사용&quot; 상태인지</li></ol><h3 id="q-세금계산서-발행이-인증서-미등록-으로-실패합니다" tabindex="-1">Q. 세금계산서 발행이 &quot;인증서 미등록&quot; 으로 실패합니다. <a class="header-anchor" href="#q-세금계산서-발행이-인증서-미등록-으로-실패합니다" aria-label="Permalink to &quot;Q. 세금계산서 발행이 &quot;인증서 미등록&quot; 으로 실패합니다.&quot;">​</a></h3><ul><li>팝빌 → 마이페이지 → <strong>인증서 관리</strong> 에서 본인 사업자 명의 공동인증서를 업로드해야 합니다.</li><li>인증서 만료 시 워크허브 측은 알지 못함 → 갱신 후 워크허브에서 재발행 시도하면 정상.</li></ul><h3 id="q-잔여-포인트가-부족하면-어떻게-되나요" tabindex="-1">Q. 잔여 포인트가 부족하면 어떻게 되나요? <a class="header-anchor" href="#q-잔여-포인트가-부족하면-어떻게-되나요" aria-label="Permalink to &quot;Q. 잔여 포인트가 부족하면 어떻게 되나요?&quot;">​</a></h3><ul><li>팝빌은 발행/조회 건당 포인트 차감 (전자세금계산서 1건당 약 80원)</li><li>잔여 부족 시 발행 API 가 &quot;잔여포인트 부족&quot; 으로 실패 → 매출 행에 실패 사유 기록</li><li>팝빌 측에서 포인트 충전 후 워크허브에서 재시도 가능</li></ul><h3 id="q-발행한-세금계산서를-취소·수정하려면" tabindex="-1">Q. 발행한 세금계산서를 취소·수정하려면? <a class="header-anchor" href="#q-발행한-세금계산서를-취소·수정하려면" aria-label="Permalink to &quot;Q. 발행한 세금계산서를 취소·수정하려면?&quot;">​</a></h3><ul><li><strong>취소</strong>: 팝빌 콘솔에서 직접 취소 — 워크허브는 콜백을 받아 상태 반영</li><li><strong>수정(수정세금계산서)</strong>: 매출 대장의 발행 행에서 <strong>[수정 발행]</strong> 버튼 → 사유 선택 → 자동 발급</li></ul><h3 id="q-운영-환경에서-외부-연동-비활성-메시지가-떠요" tabindex="-1">Q. &quot;운영 환경에서 외부 연동 비활성&quot; 메시지가 떠요. <a class="header-anchor" href="#q-운영-환경에서-외부-연동-비활성-메시지가-떠요" aria-label="Permalink to &quot;Q. &quot;운영 환경에서 외부 연동 비활성&quot; 메시지가 떠요.&quot;">​</a></h3><p>이건 워크허브 운영자(시스템관리자) 가 <code>EXTERNAL_CONN_ENC_KEY</code> 환경 키를 세팅하지 않은 상태입니다. 운영자에게 문의하세요. 자격증명 형식은 정상이지만 저장이 안 됩니다.</p><h3 id="q-팝빌-외-다른-전자세금계산서-서비스-이지오피스-등-도-지원하나요" tabindex="-1">Q. 팝빌 외 다른 전자세금계산서 서비스(이지오피스 등) 도 지원하나요? <a class="header-anchor" href="#q-팝빌-외-다른-전자세금계산서-서비스-이지오피스-등-도-지원하나요" aria-label="Permalink to &quot;Q. 팝빌 외 다른 전자세금계산서 서비스(이지오피스 등) 도 지원하나요?&quot;">​</a></h3><p>지금은 팝빌만 지원. 다른 서비스는 향후 검토 — 별도 어댑터 구현 필요.</p><hr><h2 id="_5-트러블슈팅" tabindex="-1">5. 트러블슈팅 <a class="header-anchor" href="#_5-트러블슈팅" aria-label="Permalink to &quot;5. 트러블슈팅&quot;">​</a></h2><h3 id="발행-결과가-화면에-안-보이고-처리-중-으로-머물러요" tabindex="-1">발행 결과가 화면에 안 보이고 &quot;처리 중&quot; 으로 머물러요 <a class="header-anchor" href="#발행-결과가-화면에-안-보이고-처리-중-으로-머물러요" aria-label="Permalink to &quot;발행 결과가 화면에 안 보이고 &quot;처리 중&quot; 으로 머물러요&quot;">​</a></h3><p>원인 후보:</p><ol><li><strong>워크허브 측 웹훅 미설정</strong> — 운영자가 <code>POPBILL_WEBHOOK_SECRET</code> + 팝빌 콘솔 콜백 URL 등록을 안 한 경우 → 운영자 문의</li><li><strong>팝빌 측 처리 지연</strong> — 보통 1~3분 내 완료, 드물게 10분 이상 걸리면 팝빌 측 장애 가능</li><li><strong>수동 새로고침</strong>: 매출 대장의 발행 행 우측 <strong>[상태 갱신]</strong> 버튼으로 즉시 조회 가능</li></ol><h3 id="입금내역이-안-들어와요" tabindex="-1">입금내역이 안 들어와요 <a class="header-anchor" href="#입금내역이-안-들어와요" aria-label="Permalink to &quot;입금내역이 안 들어와요&quot;">​</a></h3><p>체크:</p><ol><li>팝빌 측 계좌가 &quot;활성&quot; 상태인지 (휴면/만료된 ARS 인증)</li><li>워크허브 외부 연동 화면에서 &quot;팝빌 — 계좌조회&quot; 카드 상태가 <strong>&quot;연결됨&quot;</strong> 인지</li><li>마지막 폴링 시각이 최근 24시간 내인지 (카드에 표시)</li></ol><h3 id="같은-자격증명으로-두-모듈-모두-등록-가능" tabindex="-1">같은 자격증명으로 두 모듈 모두 등록 가능? <a class="header-anchor" href="#같은-자격증명으로-두-모듈-모두-등록-가능" aria-label="Permalink to &quot;같은 자격증명으로 두 모듈 모두 등록 가능?&quot;">​</a></h3><p>가능. 같은 팝빌 계정(LinkID + 사업자번호) 으로 전자세금계산서 + 계좌조회 둘 다 활성 가능. 포인트는 하나의 팝빌 지갑에서 공유 차감.</p><hr><h2 id="_6-보안-개인정보" tabindex="-1">6. 보안 / 개인정보 <a class="header-anchor" href="#_6-보안-개인정보" aria-label="Permalink to &quot;6. 보안 / 개인정보&quot;">​</a></h2><ul><li>자격증명은 <strong>AES-GCM 으로 암호화 후 DB 저장</strong> — 워크허브 운영자도 평문 조회 불가</li><li>마스터 키는 DB 외부 (운영 환경변수) 에 보관 — DB 덤프 유출 시에도 자격증명 보호</li><li>본 화면 응답의 SecretKey 는 항상 마스킹 (<code>••••••••</code>)</li><li>연결 해제 시 → 자격증명 즉시 삭제 (복구 불가)</li><li>팝빌 측에서 LinkID 회수 시 → 워크허브에서 자동 감지 (다음 호출에서 401) → 상태 &quot;expired&quot; 표시</li></ul><hr><h2 id="_7-운영자-시스템관리자-참고" tabindex="-1">7. 운영자 (시스템관리자) 참고 <a class="header-anchor" href="#_7-운영자-시스템관리자-참고" aria-label="Permalink to &quot;7. 운영자 (시스템관리자) 참고&quot;">​</a></h2><p>워크허브 운영자가 1회 세팅해야 하는 항목 (기관관리자와 무관):</p><table tabindex="0"><thead><tr><th>환경변수</th><th>목적</th><th>미설정 시</th></tr></thead><tbody><tr><td><code>EXTERNAL_CONN_ENC_KEY</code></td><td>자격증명 AES-GCM 마스터 키</td><td>외부 연동 모듈 전체 비활성 (503)</td></tr><tr><td><code>POPBILL_WEBHOOK_SECRET</code></td><td>발행 결과 콜백 검증</td><td>발행 결과 자동 갱신 안됨 (수동 새로고침 의존)</td></tr></tbody></table><p>팝빌 콘솔에 콜백 URL 등록:</p><ul><li>URL: <code>https://&lt;워크허브 호스트&gt;/api/finance/tax/popbill/webhook</code></li><li>secret: 위 <code>POPBILL_WEBHOOK_SECRET</code> 과 동일 값</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./modules-finance.html">재무 모듈 (관리자)</a> — 재무관리 모듈 활성화 / 메뉴 노출 정책</li><li><a href="./../02-user-guide/claude-mcp-integration.html">Claude / MCP 클라이언트 연결 (사용자 가이드)</a> — Claude 에서 매출/세금계산서 조회</li><li>매출 자동화 — 입금 매칭 (작성 예정)</li><li>아임웹 주문 동기화 (작성 예정)</li></ul>`,93)])])}const p=a(i,[["render",r]]);export{q as __pageData,p as default};
